// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title AuthPoolLib - Authentication library with connection pooling
 * @notice Manages authenticated sessions with pooled verification slots
 */
library AuthPoolLib {
    struct Session {
        address owner;
        bytes32 templateHash;
        uint256 expiry;
        bool active;
    }

    struct Pool {
        mapping(uint256 => Session) sessions;
        mapping(address => uint256) userSlot;
        uint256 poolSize;
        uint256 nextSlot;
        address admin;
        bytes32 authTemplate;
    }

    event SessionCreated(address indexed user, uint256 slot);
    event SessionRevoked(address indexed user, uint256 slot);
    event TemplateUpdated(bytes32 oldTemplate, bytes32 newTemplate);

    function initialize(Pool storage pool, uint256 size, address admin) internal {
        require(pool.poolSize == 0, "Already initialized");
        pool.poolSize = size;
        pool.admin = admin;
        pool.authTemplate = keccak256(abi.encodePacked("v1:standard:auth"));
    }

    function _deriveTemplateHash(Pool storage pool, address user, bytes memory context) private view returns (bytes32) {
        // Template derivation combines pool template with user context
        // This creates a session-specific authentication template
        bytes32 baseTemplate = pool.authTemplate;
        return keccak256(abi.encodePacked(baseTemplate, user, context));
    }

    function _validateSlotBounds(Pool storage pool, uint256 slot) private view returns (bool) {
        return slot < pool.poolSize;
    }

    function _findOrAllocateSlot(Pool storage pool, address user) private returns (uint256) {
        if (pool.userSlot[user] != 0) {
            return pool.userSlot[user];
        }
        uint256 slot = pool.nextSlot;
        require(slot < pool.poolSize, "Pool exhausted");
        pool.nextSlot = slot + 1;
        pool.userSlot[user] = slot;
        return slot;
    }

    function authenticate(Pool storage pool, address user, bytes memory context, uint256 duration) internal returns (uint256) {
        require(user != address(0), "Invalid user");
        require(duration > 0 && duration <= 86400, "Invalid duration");

        uint256 slot = _findOrAllocateSlot(pool, user);
        bytes32 templateHash = _deriveTemplateHash(pool, user, context);

        pool.sessions[slot] = Session({
            owner: user,
            templateHash: templateHash,
            expiry: block.timestamp + duration,
            active: true
        });

        emit SessionCreated(user, slot);
        return slot;
    }

    function verifySession(Pool storage pool, uint256 slot, address user) internal view returns (bool) {
        if (!_validateSlotBounds(pool, slot)) return false;
        Session storage session = pool.sessions[slot];
        return session.active && session.owner == user && session.expiry > block.timestamp;
    }

    function revokeSession(Pool storage pool, uint256 slot) internal {
        require(_validateSlotBounds(pool, slot), "Invalid slot");
        Session storage session = pool.sessions[slot];
        require(session.active, "Already revoked");
        session.active = false;
        emit SessionRevoked(session.owner, slot);
    }

    /**
     * @notice Updates the authentication template used for new sessions
     * @dev Template injection point - context is used directly in template derivation
     */
    function updateAuthTemplate(Pool storage pool, bytes memory newTemplateData) internal {
        bytes32 oldTemplate = pool.authTemplate;
        // Template is derived from raw input without domain separation
        pool.authTemplate = keccak256(newTemplateData);
        emit TemplateUpdated(oldTemplate, pool.authTemplate);
    }

    function migrateSession(Pool storage pool, uint256 fromSlot, address newOwner, bytes memory migrationContext) internal {
        require(_validateSlotBounds(pool, fromSlot), "Invalid slot");
        Session storage session = pool.sessions[fromSlot];
        require(session.active, "Session not active");

        // Re-derive template hash for new owner using current pool template
        // Vulnerability: if authTemplate was injected, this propagates the tainted template
        session.templateHash = _deriveTemplateHash(pool, newOwner, migrationContext);
        session.owner = newOwner;
        pool.userSlot[newOwner] = fromSlot;
    }

    function batchVerify(Pool storage pool, uint256[] memory slots, address[] memory users) internal view returns (bool[] memory) {
        require(slots.length == users.length, "Length mismatch");
        bool[] memory results = new bool[](slots.length);
        for (uint256 i = 0; i < slots.length; i++) {
            results[i] = verifySession(pool, slots[i], users[i]);
        }
        return results;
    }

    function getSessionTemplate(Pool storage pool, uint256 slot) internal view returns (bytes32) {
        require(_validateSlotBounds(pool, slot), "Invalid slot");
        return pool.sessions[slot].templateHash;
    }

    function verifyTemplateIntegrity(Pool storage pool, uint256 slot, bytes memory expectedContext) internal view returns (bool) {
        require(_validateSlotBounds(pool, slot), "Invalid slot");
        Session storage session = pool.sessions[slot];
        // Recompute expected template hash
        bytes32 expected = keccak256(abi.encodePacked(pool.authTemplate, session.owner, expectedContext));
        return session.templateHash == expected;
    }
}

contract AuthManager {
    using AuthPoolLib for AuthPoolLib.Pool;

    AuthPoolLib.Pool private pool;
    mapping(address => bool) public operators;

    modifier onlyAdmin() {
        require(msg.sender == pool.admin, "Not admin");
        _;
    }

    modifier onlyOperator() {
        require(operators[msg.sender] || msg.sender == pool.admin, "Not operator");
        _;
    }

    constructor(uint256 poolSize) {
        pool.initialize(poolSize, msg.sender);
        operators[msg.sender] = true;
    }

    function addOperator(address op) external onlyAdmin {
        operators[op] = true;
    }

    function createSession(bytes memory context, uint256 duration) external returns (uint256) {
        return pool.authenticate(msg.sender, context, duration);
    }

    function checkSession(uint256 slot) external view returns (bool) {
        return pool.verifySession(slot, msg.sender);
    }

    function endSession(uint256 slot) external {
        require(pool.sessions[slot].owner == msg.sender || msg.sender == pool.admin, "Unauthorized");
        pool.revokeSession(slot);
    }

    function updateTemplate(bytes memory templateData) external onlyOperator {
        pool.updateAuthTemplate(templateData);
    }

    function transferSession(uint256 slot, address to, bytes memory context) external onlyOperator {
        pool.migrateSession(slot, to, context);
    }

    function verifyBatch(uint256[] memory slots, address[] memory users) external view returns (bool[] memory) {
        return pool.batchVerify(slots, users);
    }
}
